import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());

        // Known constructive solution for this classic problem:
        // Build numbers from even numbers and multiples of 3, excluding multiples of 6,
        // then adjust so total sum is divisible by 6.
        //
        // For each chosen ai:
        // - ai is divisible by 2 or 3
        // - sum(all) is divisible by 6
        // Then sum(all)-ai shares factor 2 or 3 with ai, so gcd(ai, sum- ai) > 1.
        //
        // Also, by including some numbers only divisible by 2 and some only by 3,
        // the gcd of all elements becomes 1.

        if (N == 3) {
            // Special small case
            System.out.println("2 5 63");
            return;
        }
        if (N == 4) {
            // Special small case
            System.out.println("2 5 20 63");
            return;
        }

        ArrayList<Integer> cand = new ArrayList<>();
        for (int i = 2; i <= 30000; i++) {
            if (i % 2 == 0 || i % 3 == 0) {
                if (i % 6 != 0) cand.add(i);
            }
        }

        ArrayList<Integer> ans = new ArrayList<>();
        long sum = 0;
        for (int i = 0; i < N - 2; i++) {
            int x = cand.get(i);
            ans.add(x);
            sum += x;
        }

        // Add two multiples of 6 so that total sum % 6 == 0
        // Use distinct values within limit.
        int[] sixes = {6, 12, 18};
        boolean found = false;
        for (int i = 0; i < sixes.length && !found; i++) {
            for (int j = i + 1; j < sixes.length && !found; j++) {
                long total = sum + sixes[i] + sixes[j];
                if (total % 6 == 0) {
                    ans.add(sixes[i]);
                    ans.add(sixes[j]);
                    found = true;
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < ans.size(); i++) {
            if (i > 0) sb.append(' ');
            sb.append(ans.get(i));
        }
        System.out.println(sb.toString());
    }
}
